# CERT-SUB (static): every graph arm's stepped matrix is EXACTLY the base
# matrix with the removed cells' rows and columns deleted, and its init /
# noise / pool / mech / motor / drive maps are the base's maps restricted to
# the kept cells (covers the old-closure removal path the relay exercises).
def _coo_gi(Wm, gi_of_loc):
    crow = Wm.crow_indices().numpy()
    col = Wm.col_indices().numpy()
    row = np.repeat(np.arange(len(crow) - 1), np.diff(crow))
    d, s_ = gi_of_loc[row], gi_of_loc[col]
    o = np.lexsort((s_, d))
    return d[o], s_[o], Wm.values().numpy()[o]


