def _premotor(side):
    mn = np.concatenate([MN[f"Ti_f{side}"], MN[f"Ti_e{side}"]])
    s_ = np.unique(src_all[emask_wA & np.isin(dst_all, mn)])
    return s_[~is_motor_g[s_]]


